raw_shacl_shapes:
@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix agt:   <http://mnemosyne.dev/agent#> .
@prefix mem:   <http://mnemosyne.dev/memory#> .
@prefix mnemo: <https://mnemosyne.local/ns#> .
@prefix prov:  <http://www.w3.org/ns/prov#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .

# I1 (HARD/structural via sh:select): a record INSIDE a per-observer membrane
# (…:projection:memory:agent:) MUST be observedBy exactly one agt:Agent. The
# COMMONS (un-segmented graph, empty observer, legally no mem:observedBy) is NOT
# targeted - observedBy is OPTIONAL at L0.
agt:I1_MembraneWitnessShape a sh:NodeShape ;
    sh:targetClass mem:MemoryRecord ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "I1: a record INSIDE a per-observer membrane (…:projection:memory:agent:) MUST be observedBy exactly one agt:Agent. (Commons records, in the un-segmented graph, are exempt - observedBy is optional at L0.)" ;
        sh:prefixes [ sh:declare [ sh:prefix "mem" ; sh:namespace "http://mnemosyne.dev/memory#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              GRAPH ?g { $this a mem:MemoryRecord . }
              FILTER( CONTAINS(STR(?g), ':projection:memory:agent:') )
              FILTER NOT EXISTS { GRAPH ?g { $this mem:observedBy ?obs . } }
            }
        """ ;
    ] .

# I1b (FlagAndAccept/IRI-surgery): observedBy leaf == the {id} segment of the
# membrane graph. Requires the spec-§4 unified stem to pass - keep FlagAndAccept until then.
agt:I1b_MembraneOwnerShape a sh:NodeShape ;
    sh:targetClass mem:MemoryRecord ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "I1b: a record's mem:observedBy agent token MUST equal the {id} segment of its membrane graph." ;
        sh:prefixes [ sh:declare [ sh:prefix "mem" ; sh:namespace "http://mnemosyne.dev/memory#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              GRAPH ?g { $this mem:observedBy ?obs . }
              FILTER( CONTAINS(STR(?g), ':projection:memory:agent:') )
              BIND( STRAFTER(STR(?g),  ':projection:memory:agent:') AS ?seg )
              BIND( STRAFTER(STR(?obs), 'urn:sophia:agent:')        AS ?obsLeaf )
              FILTER( ?seg != ?obsLeaf )
            }
        """ ;
    ] .

# I1-Song (HARD): the Song membrane graph is attributed to the agent.
agt:I1_SongMembraneShape a sh:NodeShape ;
    sh:targetClass mnemo:Song ;
    sh:property [
        sh:path prov:wasAttributedTo ; sh:minCount 1 ; sh:class agt:Agent ;
        sh:severity sh:Violation ;
        sh:message "I1: a Song's membrane MUST be prov:wasAttributedTo an agt:Agent." ;
    ] .

# I1-Valuation (ADVISORY): check the MEMBRANE, not a never-present mem:observedBy
# triple. Warns when a valuation's graph lacks an :agent: segment - the actual gap (ask #5).
agt:I1_ValuationMembraneAdvisory a sh:NodeShape ;
    sh:targetClass mnemo:BlockValuation ;
    sh:sparql [
        sh:severity sh:Warning ;
        sh:message "I1-advisory: this BlockValuation lives in a NON-witness-scoped salience graph (no :agent:{id} segment) - salience is the one Geist surface still global/commons. EA-3 ask #5: fork salience per observer (…:projection:salience:agent:{id})." ;
        sh:prefixes [ sh:declare [ sh:prefix "mnemo" ; sh:namespace "https://mnemosyne.local/ns#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              GRAPH ?g { $this a mnemo:BlockValuation . }
              FILTER( CONTAINS(STR(?g), ':projection:salience') )
              FILTER( !CONTAINS(STR(?g), ':projection:salience:agent:') )
            }
        """ ;
    ] .

# I2 (FlagAndAccept until §4): when a record carries BOTH a voice leaf and a
# witness, the leaf MUST name an agt:Voice voiceOf that observedBy agent.
agt:I2_VoiceContainmentShape a sh:NodeShape ;
    sh:targetClass mem:MemoryRecord ;
    sh:property [ sh:path mem:agentId ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "I2: when a record carries BOTH a voice leaf (mem:agentId) and a witness (mem:observedBy), the leaf MUST name an agt:Voice voiceOf that observedBy agent - a voice cannot author testimony outside its agent." ;
        sh:prefixes [ sh:declare [ sh:prefix "agt" ; sh:namespace "http://mnemosyne.dev/agent#" ] ,
                                  [ sh:prefix "mem" ; sh:namespace "http://mnemosyne.dev/memory#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              $this mem:agentId ?vid ; mem:observedBy ?agent .
              FILTER NOT EXISTS {
                ?voice a agt:Voice ; agt:voiceId ?vid ; agt:voiceOf ?agent .
              }
            }
        """ ;
    ] .

# I2b (HARD): inside a per-observer membrane, a voice leaf MUST also carry the
# agent witness. In the commons a leaf-only record is tolerated.
agt:I2b_VoiceNeedsWitnessShape a sh:NodeShape ;
    sh:targetClass mem:MemoryRecord ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "I2b: inside a per-observer membrane, a record with a voice leaf (mem:agentId) MUST also carry the agent witness (mem:observedBy) - a voice cannot exist without its owning agent." ;
        sh:prefixes [ sh:declare [ sh:prefix "mem" ; sh:namespace "http://mnemosyne.dev/memory#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              GRAPH ?g { $this mem:agentId ?vid . }
              FILTER( CONTAINS(STR(?g), ':projection:memory:agent:') )
              FILTER NOT EXISTS { GRAPH ?g { $this mem:observedBy ?obs . } }
            }
        """ ;
    ] .

# I3a/b (HARD/structural): voicing is exactly-one from the closed enum.
agt:I3_VoicingShape a sh:NodeShape ;
    sh:targetClass agt:Agent ;
    sh:property [
        sh:path agt:voicing ; sh:minCount 1 ; sh:maxCount 1 ;
        sh:in ( agt:Monovocal agt:Parliament ) ; sh:severity sh:Violation ;
        sh:message "I3: every agent has exactly one voicing, drawn from {Monovocal, Parliament}." ;
    ] .

# I3c (HARD via sh:select): Monovocal <=> exactly one voice; Parliament <=> >=2.
agt:I3_CardinalityShape a sh:NodeShape ;
    sh:targetClass agt:Agent ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "I3: a Monovocal agent MUST have exactly one agt:Voice; a Parliament MUST have >=2 (a 1-voice Parliament is functionally Monovocal - forbidden so the graph determines the mode)." ;
        sh:prefixes [ sh:declare [ sh:prefix "agt" ; sh:namespace "http://mnemosyne.dev/agent#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              $this agt:voicing ?mode .
              { SELECT $this (COUNT(?v) AS ?n) WHERE { ?v agt:voiceOf $this } GROUP BY $this }
              FILTER ( (?mode = agt:Monovocal  && ?n != 1) ||
                       (?mode = agt:Parliament && ?n < 2) )
            }
        """ ;
    ] .

# I3d (ADVISORY): a Monovocal agent's records SHOULD elide the redundant voice leaf.
agt:I3d_MonovocalElisionAdvisory a sh:NodeShape ;
    sh:targetClass mem:MemoryRecord ;
    sh:sparql [
        sh:severity sh:Warning ;
        sh:message "I3d-advisory: this record carries a mem:agentId leaf but its witnessing agent is Monovocal - the leaf is redundant and SHOULD be elided." ;
        sh:prefixes [ sh:declare [ sh:prefix "agt" ; sh:namespace "http://mnemosyne.dev/agent#" ] ,
                                  [ sh:prefix "mem" ; sh:namespace "http://mnemosyne.dev/memory#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              $this mem:agentId ?vid ; mem:observedBy ?agent .
              ?agent agt:voicing agt:Monovocal .
            }
        """ ;
    ] .

# I4a (HARD/structural): a voice borrows exactly one agent and owns no membrane.
agt:I4_BorrowShape a sh:NodeShape ;
    sh:targetClass agt:Voice ;
    sh:property [
        sh:path agt:voiceOf ; sh:minCount 1 ; sh:maxCount 1 ; sh:class agt:Agent ;
        sh:severity sh:Violation ;
        sh:message "I4a: a voice borrows exactly one agent's membrane (voiceOf, single)." ;
    ] ;
    sh:property [
        sh:path agt:ownsMembrane ; sh:maxCount 0 ; sh:severity sh:Violation ;
        sh:message "I4a: a voice MUST NOT own a membrane - it borrows its agent's (attribution at the leaf, no graph of its own)." ;
    ] .

# I4b (FlagAndAccept until §4): a voiced record's observedBy is the AGENT, not the voice.
agt:I4b_SharedObserverShape a sh:NodeShape ;
    sh:targetClass mem:MemoryRecord ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "I4b: a voiced record's mem:observedBy is the agent's witness IRI urn:sophia:agent:{agentId} - voices share it, they don't mint their own." ;
        sh:prefixes [ sh:declare [ sh:prefix "agt" ; sh:namespace "http://mnemosyne.dev/agent#" ] ,
                                  [ sh:prefix "mem" ; sh:namespace "http://mnemosyne.dev/memory#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              $this mem:agentId ?vid ; mem:observedBy ?obs .
              ?voice a agt:Voice ; agt:voiceId ?vid ; agt:voiceOf ?agent .
              ?agent agt:agentId ?aid .
              FILTER ( STR(?obs) != CONCAT('urn:sophia:agent:', ?aid) )
            }
        """ ;
    ] .

# IDENTITY UNIFICATION (spec §4): subject IRI == urn:sophia:agent:{agentId}.
# §4 is LANDED on choreograph main so this is Halt-eligible now.
agt:IdentityUnificationShape a sh:NodeShape ;
    sh:targetClass agt:Agent ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "Identity unification: the agt:Agent subject IRI MUST equal urn:sophia:agent:{agentId} (the unified stem; §4 landed)." ;
        sh:prefixes [ sh:declare [ sh:prefix "agt" ; sh:namespace "http://mnemosyne.dev/agent#" ] ] ;
        sh:select """
            SELECT $this WHERE {
              $this agt:agentId ?id .
              FILTER( STR($this) != CONCAT('urn:sophia:agent:', ?id) )
            }
        """ ;
    ] .
